// ---------------- output ----------------
const dir = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'src', 'i18n');
const seen = new Set();
for (const [k] of rows) { if (seen.has(k)) throw new Error(`duplicate key ${k}`); seen.add(k); }
['en', 'ru', 'kk'].forEach((lang, i) => {
  const obj = {};
  for (const r of rows) { if (!r[i + 1]) throw new Error(`missing ${lang} for ${r[0]}`); obj[r[0]] = r[i + 1]; }
  fs.writeFileSync(path.join(dir, `${lang}.json`), JSON.stringify(obj, null, 1) + '\n');
});
console.log(`i18n: ${rows.length} keys × 3 languages`);
